namespace Jindan.Engine.Package;

public sealed class PackageException(string code, string message) : Exception(message) { public string Code { get; } = code; }
public sealed record PackageLimits(int MaxEntries = 20000, long MaxExpandedBytes = 256L * 1024 * 1024, long MaxXmlBytes = 48L * 1024 * 1024, long MaxInputBytes = 160L * 1024 * 1024);
public sealed record PackageEntry(string Name, long Size, string Sha256);
public sealed record SectionInventory(string Name, int Paragraphs, int TextSlots, int Cells, int Pictures, string SlotTextSha256);
public sealed record PackageInventory(string Sha256, IReadOnlyList<PackageEntry> Entries, IReadOnlyList<SectionInventory> Sections, bool ManifestValidated, bool ReportReady = false);
public sealed record RecoveryRecord(string Id, string Role, string Filename, string Sha256, long Size, string Entry, IReadOnlyList<string> ParentIds, bool RequiresReanalysis);
public sealed record RecoveryInventory(string Sha256, string ProjectId, IReadOnlyList<RecoveryRecord> Files, bool StandaloneMetadataPreserved = false, bool ReportReady = false);
public static partial class NativePackage
{
    static void Need([DoesNotReturnIf(false)] bool condition, string code, string message) { if (!condition) throw new PackageException(code, message); }
    static string Hash(ReadOnlySpan<byte> bytes) => Convert.ToHexStringLower(SHA256.HashData(bytes));
    [GeneratedRegex(@"^Contents/section\d+\.xml$", RegexOptions.CultureInvariant)] private static partial Regex SectionName();
    [GeneratedRegex(@"^[a-f0-9]{64}$", RegexOptions.CultureInvariant)] private static partial Regex ShaPattern();
    [GeneratedRegex(@"^[a-zA-Z0-9_.:-]{1,180}$", RegexOptions.CultureInvariant)] private static partial Regex FileId();
    static bool SafeName(string name) { var parts = name.Split('/'); return name.Length > 0 && !name.StartsWith('/') && !name.Contains('\\') && !name.Contains(':') && !name.Contains("..", StringComparison.Ordinal) && !name.Any(char.IsControl) && !parts.Where((p, i) => p is ".." or "." || p.Length == 0 && i != parts.Length - 1).Any(); }
    static Dictionary<string, byte[]> ReadZip(ReadOnlySpan<byte> bytes, PackageLimits limits, CancellationToken ct) { Need(limits.MaxEntries is > 0 and <= 20000 && limits.MaxExpandedBytes is > 0 and <= 520L * 1024 * 1024 && limits.MaxXmlBytes is > 0 and <= 48L * 1024 * 1024 && limits.MaxInputBytes is > 0 and <= 512L * 1024 * 1024, "INVALID_LIMIT", "Native package limits must be bounded."); Need(bytes.Length >= 22 && bytes.Length <= limits.MaxInputBytes, "INVALID_ARCHIVE", "Archive input size is invalid."); try { using var input = new MemoryStream(bytes.ToArray(), false); using var zip = new ZipArchive(input, ZipArchiveMode.Read); Need(zip.Entries.Count > 0 && zip.Entries.Count <= limits.MaxEntries, "INVALID_ARCHIVE", "Archive entry count exceeds the boundary."); var entries = new Dictionary<string, byte[]>(StringComparer.Ordinal); long total = 0; foreach (var entry in zip.Entries) { ct.ThrowIfCancellationRequested(); Need(SafeName(entry.FullName) && !entries.ContainsKey(entry.FullName), "INVALID_ARCHIVE", "Duplicate or unsafe ZIP entry names are forbidden."); Need(entry.Length >= 0 && entry.Length <= limits.MaxExpandedBytes - total, "INVALID_ARCHIVE", "Expanded archive exceeds the boundary."); total += entry.Length; Need(!entry.FullName.EndsWith(".xml", StringComparison.OrdinalIgnoreCase) || entry.Length <= limits.MaxXmlBytes, "INVALID_ARCHIVE", "XML entry exceeds the boundary."); using var source = entry.Open(); using var output = new MemoryStream(); var buffer = new byte[64 * 1024]; int count; long read = 0; while ((count = source.Read(buffer)) > 0) { ct.ThrowIfCancellationRequested(); read += count; Need(read <= entry.Length, "INVALID_ARCHIVE", "ZIP declared and actual sizes differ."); output.Write(buffer, 0, count); } Need(read == entry.Length, "INVALID_ARCHIVE", "ZIP entry is truncated."); entries.Add(entry.FullName, output.ToArray()); } return entries; } catch (PackageException) { throw; } catch (Exception e) when (e is InvalidDataException or IOException or ArgumentException or OverflowException) { throw new PackageException("INVALID_ARCHIVE", "Malformed or unsupported ZIP archive."); } }
    static string ManifestPath(string href, Dictionary<string, byte[]> entries) { Need(!href.StartsWith('/') && !href.Contains('\\') && !href.Contains(':') && !href.Any(char.IsControl), "INVALID_MANIFEST", "Unsafe manifest reference."); if (entries.ContainsKey(href)) return href; var parts = new List<string> { "Contents" }; foreach (var part in href.Split('/')) { if (part == ".") continue; if (part == "..") { Need(parts.Count > 0, "INVALID_MANIFEST", "Manifest reference escapes package root."); parts.RemoveAt(parts.Count - 1); } else { Need(part.Length > 0, "INVALID_MANIFEST", "Empty manifest path component."); parts.Add(part); } } var path = string.Join('/', parts); Need(entries.ContainsKey(path), "INVALID_MANIFEST", "Manifest references a missing entry."); return path; }
    static XDocument Xml(byte[] bytes, long max) { try { var settings = new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit, XmlResolver = null, MaxCharactersInDocument = max, MaxCharactersFromEntities = 0 }; using var input = new MemoryStream(bytes, false); using var reader = XmlReader.Create(input, settings); return XDocument.Load(reader, LoadOptions.PreserveWhitespace); } catch (Exception e) when (e is XmlException or InvalidOperationException) { throw new PackageException("INVALID_XML", "Document XML is malformed or contains prohibited declarations."); } }
    static string SlotText(XElement t) { var result = new StringBuilder(); foreach (var n in t.Nodes()) { if (n is XText text) result.Append(text.Value); else if (n is XElement child && child.Name.LocalName == "lineBreak") result.Append('\n'); else if (n is XElement tab && tab.Name.LocalName == "tab") result.Append('\t'); else return ""; } return result.ToString(); }
    public static PackageInventory InspectHwpx(ReadOnlyMemory<byte> input, PackageLimits? limits = null, bool validateManifest = true, CancellationToken ct = default)
    {
        ct.ThrowIfCancellationRequested(); var bytes = input.ToArray(); limits ??= new(); var entries = ReadZip(bytes, limits, ct); var sections = entries.Keys.Where(k => SectionName().IsMatch(k)).Order(StringComparer.Ordinal).ToArray(); Need(sections.Length > 0, "MISSING_SECTION", "HWPX contains no body section."); Need(!entries.Keys.Any(k => Regex.IsMatch(k, "signatures?|encryption", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)), "PROTECTED_DOCUMENT", "Signed/encrypted documents are not writable inputs."); var documents = new Dictionary<string, XDocument>(StringComparer.Ordinal); foreach (var entry in entries.Where(e => e.Key.EndsWith(".xml", StringComparison.OrdinalIgnoreCase) || e.Key == "Contents/content.hpf")) { ct.ThrowIfCancellationRequested(); Need(entry.Value.LongLength <= limits.MaxXmlBytes, "INVALID_XML", "XML exceeds the shared limit."); documents[entry.Key] = Xml(entry.Value, limits.MaxXmlBytes); }
        if (validateManifest) { Need(documents.TryGetValue("Contents/content.hpf", out var manifest), "MISSING_MANIFEST", "A manifest is required for native structural validation."); var items = manifest!.Descendants().Where(e => e.Name.LocalName == "item").ToArray(); var byId = new Dictionary<string, string>(StringComparer.Ordinal); foreach (var item in items) { var id = (string?)item.Attribute("id"); var href = (string?)item.Attribute("href"); Need(!string.IsNullOrEmpty(id) && !string.IsNullOrEmpty(href) && byId.TryAdd(id, ManifestPath(href, entries)), "INVALID_MANIFEST", "Manifest items need unique IDs and safe paths."); } foreach (var section in sections) Need(byId.Values.Contains(section, StringComparer.Ordinal), "INVALID_MANIFEST", "A body section is not registered in the manifest."); var refs = manifest.Descendants().Where(e => e.Name.LocalName == "itemref").Select(e => (string?)e.Attribute("idref")).ToArray(); Need(refs.Length > 0 && refs.All(id => id is not null && byId.ContainsKey(id)) && refs.Distinct(StringComparer.Ordinal).Count() == refs.Length, "INVALID_MANIFEST", "Spine references are missing or duplicated."); foreach (var section in sections) Need(refs.Any(id => byId[id!] == section), "INVALID_MANIFEST", "A body section is missing from the spine."); }
        var inventory = sections.Select(name => { var nodes = documents[name].Descendants().ToArray(); var texts = nodes.Where(n => n.Name.LocalName == "t" && n.Ancestors().Any(p => p.Name.LocalName == "p")).Select(SlotText); return new SectionInventory(name, nodes.Count(n => n.Name.LocalName == "p"), texts.Count(), nodes.Count(n => n.Name.LocalName == "tc"), nodes.Count(n => n.Name.LocalName == "pic"), Hash(Encoding.UTF8.GetBytes(string.Join('\0', texts)))); }).ToArray(); return new(Hash(bytes), entries.Select(e => new PackageEntry(e.Key, e.Value.LongLength, Hash(e.Value))).OrderBy(e => e.Name, StringComparer.Ordinal).ToArray(), inventory, validateManifest);
    }
    public static RecoveryInventory VerifyRecovery(ReadOnlyMemory<byte> input, string? projectId = null, string? expectedSha256 = null, CancellationToken ct = default)
    {
        ct.ThrowIfCancellationRequested(); var bytes = input.ToArray(); var sha = Hash(bytes); Need(expectedSha256 is null || expectedSha256 == sha, "BINDING_MISMATCH", "Recovery archive SHA differs."); var entries = ReadZip(bytes, new(1001, 520L * 1024 * 1024, 8L * 1024 * 1024, 512L * 1024 * 1024), ct); Need(entries.TryGetValue("recovery.json", out var json) && json.Length <= 8 * 1024 * 1024, "INVALID_RECOVERY", "Recovery manifest is missing or too large."); foreach (var name in entries.Keys) Need(name == "recovery.json" || name.StartsWith("files/", StringComparison.Ordinal) && name.EndsWith(".bin", StringComparison.Ordinal) && ShaPattern().IsMatch(name[6..^4]), "INVALID_RECOVERY", "Unexpected recovery payload name."); try
        {
            using var doc = JsonDocument.Parse(json!, new JsonDocumentOptions { MaxDepth = 128 }); RejectPrototypeKeys(doc.RootElement); var m = doc.RootElement; Need(m.GetProperty("schema").GetString() == "jindan-engine-recovery/1" && m.GetProperty("recoveryMode").GetString() == "project-assisted" && m.GetProperty("reportReady").ValueKind == JsonValueKind.False, "INVALID_RECOVERY", "Unsupported recovery contract."); var project = m.GetProperty("projectId").GetString(); Need(project is not null && Regex.IsMatch(project, @"^project:[a-zA-Z0-9_.:%-]{1,160}$", RegexOptions.CultureInvariant), "INVALID_RECOVERY", "Invalid recovery project."); Need(projectId is null || projectId == project, "BINDING_MISMATCH", "Recovery belongs to another project."); var records = m.GetProperty("files"); Need(records.ValueKind == JsonValueKind.Array && records.GetArrayLength() is > 0 and <= 1000, "INVALID_RECOVERY", "Recovery requires1..1000 records."); var byId = new Dictionary<string, RecoveryRecord>(StringComparer.Ordinal); var used = new HashSet<string>(StringComparer.Ordinal) { "recovery.json" }; var roles = new[] { "source", "candidate", "native-saved", "evidence", "collection", "draft" }; foreach (var r in records.EnumerateArray()) { ct.ThrowIfCancellationRequested(); var id = r.GetProperty("id").GetString(); var role = r.GetProperty("role").GetString(); var filename = r.GetProperty("filename").GetString(); var hash = r.GetProperty("sha256").GetString(); var entry = r.GetProperty("entry").GetString(); var size = r.GetProperty("size").GetInt64(); Need(id is not null && FileId().IsMatch(id) && !byId.ContainsKey(id) && roles.Contains(role) && filename is { Length: > 0 and <= 1000 } && hash is not null && ShaPattern().IsMatch(hash) && entry == "files/" + hash + ".bin", "INVALID_RECOVERY", "Invalid recovery record identity."); Need(entries.TryGetValue(entry!, out var data) && data.LongLength == size && size is > 0 and <= 160L * 1024 * 1024, "INVALID_RECOVERY", "Recovery file size or payload is invalid."); Need(Hash(data!) == hash, "BINDING_MISMATCH", "Recovery file hash differs."); var parents = r.GetProperty("parentIds"); Need(parents.ValueKind == JsonValueKind.Array && parents.GetArrayLength() <= 100, "INVALID_RECOVERY", "Invalid recovery parent list."); var parentIds = parents.EnumerateArray().Select(p => p.GetString() ?? "").ToArray(); Need(parentIds.Distinct(StringComparer.Ordinal).Count() == parentIds.Length, "INVALID_RECOVERY", "Recovery parents are duplicated."); var record = new RecoveryRecord(id!, role!, filename!, hash!, size, entry!, parentIds, role == "native-saved"); byId.Add(id!, record); used.Add(entry!); }
            foreach (var r in byId.Values) { Need(r.ParentIds.All(id => byId.ContainsKey(id) && id != r.Id), "INVALID_RECOVERY", "Recovery parent is missing or self-referential."); Need(r.Role != "source" || r.ParentIds.Count == 0, "INVALID_RECOVERY", "Immutable sources cannot have parents."); Need(r.Role is not ("candidate" or "native-saved" or "collection" or "draft") || r.ParentIds.Count > 0, "INVALID_RECOVERY", "Derived recovery files require parents."); }
            var active = new HashSet<string>(StringComparer.Ordinal); var done = new HashSet<string>(StringComparer.Ordinal); void Visit(string id) { Need(!active.Contains(id), "INVALID_RECOVERY", "Recovery derivation cycle."); if (done.Contains(id)) return; active.Add(id); foreach (var p in byId[id].ParentIds) Visit(p); active.Remove(id); done.Add(id); }
            foreach (var id in byId.Keys) Visit(id); Need(used.Count == entries.Count, "INVALID_RECOVERY", "Recovery has unregistered payloads."); return new(sha, project!, byId.Values.ToArray());
        }
        catch (PackageException) { throw; }
        catch (Exception e) when (e is JsonException or KeyNotFoundException or InvalidOperationException or FormatException or OverflowException) { throw new PackageException("INVALID_RECOVERY", "Malformed recovery manifest."); }
    }
    static void RejectPrototypeKeys(JsonElement e, int depth = 0) { Need(depth <= 64, "INVALID_RECOVERY", "Recovery state nesting exceeds the shared limit."); if (e.ValueKind == JsonValueKind.Number) Need(e.TryGetDouble(out var number) && double.IsFinite(number), "INVALID_RECOVERY", "Recovery numbers must be finite."); if (e.ValueKind == JsonValueKind.Object) { var keys = new HashSet<string>(StringComparer.Ordinal); foreach (var p in e.EnumerateObject()) { Need(keys.Add(p.Name) && p.Name is not ("__proto__" or "prototype" or "constructor"), "INVALID_RECOVERY", "Unsafe or duplicate recovery JSON key."); RejectPrototypeKeys(p.Value, depth + 1); } } else if (e.ValueKind == JsonValueKind.Array) foreach (var item in e.EnumerateArray()) RejectPrototypeKeys(item, depth + 1); }
